DIR *dir_stream;
struct dirent *entry;

// Allocate/Open stream, returns opaque pointer DIR*
dir_stream = opendir("/usr/bin");

if (dir_stream == NULL) return; 

// Read entries sequentially until EOF (NULL)
while ((entry = readdir(dir_stream)) != NULL) {
    // Access entry metadata using struct dirent
    const char *name = entry->d_name;
    int type = entry->d_type; // DT_REG, DT_DIR, etc.
}

// Close and release the DIR structure
closedir(dir_stream);
